function x($s) { return htmlspecialchars($s, ENT_XML1 | ENT_QUOTES, 'UTF-8'); }
function r($text, $bold=false, $size=21, $color='000000') {
  $b=$bold?'<w:b/>':''; return '<w:r><w:rPr>'.$b.'<w:color w:val="'.$color.'"/><w:sz w:val="'.$size.'"/><w:szCs w:val="'.$size.'"/><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/></w:rPr><w:t xml:space="preserve">'.x($text).'</w:t></w:r>';
}
function field($instruction, $placeholder='') {
  return '<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve">'.x($instruction).'</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r>'.($placeholder === '' ? '' : r($placeholder,false,19,'5A6772')).'<w:r><w:fldChar w:fldCharType="end"/></w:r>';
}
function toc() {
  return '<w:p><w:pPr><w:pStyle w:val="H1"/><w:spacing w:before="200" w:after="130"/></w:pPr>'.r('Contents',true,30).'</w:p>'
    .'<w:p><w:pPr><w:spacing w:after="160"/></w:pPr>'.r('Use this table to move through the guide. In Microsoft Word, right-click the table and choose Update Field if the page numbers need refreshing.',false,20,'5A6772').'</w:p>'
    .'<w:p><w:pPr><w:spacing w:after="120"/></w:pPr>'.field('TOC \\o "1-2" \\h \\z \\u','Update table of contents').'</w:p>';
}
function p($text='', $style=null, $bold=false, $size=21, $color='000000', $page=false) {
  $pr=''; if($style) $pr.='<w:pStyle w:val="'.$style.'"/>'; if($page) $pr.='<w:pageBreakBefore/>';
  return '<w:p><w:pPr>'.$pr.'</w:pPr>'.r($text,$bold,$size,$color).'</w:p>';
}
function bullets($items, $numbered=false) { $o=''; foreach($items as $t) $o.='<w:p><w:pPr><w:pStyle w:val="'.($numbered?'ListNumber':'ListBullet').'"/></w:pPr>'.r($t,false,20).'</w:p>'; return $o; }
function table($headers,$rows,$widths) {
  $o='<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="6" w:color="D9D9D9"/><w:left w:val="single" w:sz="6" w:color="D9D9D9"/><w:bottom w:val="single" w:sz="6" w:color="D9D9D9"/><w:right w:val="single" w:sz="6" w:color="D9D9D9"/><w:insideH w:val="single" w:sz="6" w:color="D9D9D9"/><w:insideV w:val="single" w:sz="6" w:color="D9D9D9"/></w:tblBorders><w:tblCellMar><w:top w:w="90" w:type="dxa"/><w:left w:w="120" w:type="dxa"/><w:bottom w:w="90" w:type="dxa"/><w:right w:w="120" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>';
  foreach($widths as $w) $o.='<w:gridCol w:w="'.$w.'"/>'; $o.='</w:tblGrid><w:tr><w:trPr><w:tblHeader/></w:trPr>';
  foreach($headers as $i=>$h) $o.='<w:tc><w:tcPr><w:tcW w:w="'.$widths[$i].'" w:type="dxa"/><w:shd w:fill="163A5F"/></w:tcPr><w:p>'.r($h,true,19,'FFFFFF').'</w:p></w:tc>';
  $o.='</w:tr>';
  foreach($rows as $n=>$row) { $o.='<w:tr>'; foreach($row as $i=>$v) { $shade=$n%2?'<w:shd w:fill="EAF2F8"/>':''; $o.='<w:tc><w:tcPr><w:tcW w:w="'.$widths[$i].'" w:type="dxa"/>'.$shade.'</w:tcPr><w:p>'.r($v,false,18).'</w:p></w:tc>'; } $o.='</w:tr>'; }
  return $o.'</w:tbl><w:p/>';
}
function screenshot($relId, $imageId, $name, $caption) {
  $cx = 5850000; $cy = 3290625;
  $drawing = '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="80" w:after="40"/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="'.$cx.'" cy="'.$cy.'"/><wp:effectExtent l="0" t="0" r="0" b="0"/><wp:docPr id="'.$imageId.'" name="'.x($name).'" descr="'.x($caption).'"/><wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="'.x($name).'"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="'.$relId.'"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'.$cx.'" cy="'.$cy.'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';
  return $drawing.'<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:after="130"/></w:pPr>'.r($caption,false,18,'5A6772').'</w:p>';
}
